using System.Collections.Concurrent;
using System.Text.Json.Nodes;
using InspectAzureAI.Eval.Context;
using InspectAzureAI.Provider.Core;

namespace InspectAzureAI.Eval.Approval;

/// <summary>
/// Port of the <c>approval/_approver.py</c> <c>Approver</c> protocol: decides on one tool call.
/// </summary>
/// <param name="message">Message generated by the model along with the tool call.</param>
/// <param name="call">The tool call to be approved.</param>
/// <param name="view">Custom rendering of tool context and call.</param>
/// <param name="history">The current conversation history (ending with the assistant turn under review).</param>
/// <param name="cancellationToken">Cancels a pending decision (a human prompt, a model consulted by the approver).</param>
public delegate Task<Approval> Approver(
    string message,
    ToolCall call,
    ToolCallView view,
    IReadOnlyList<ChatMessage> history,
    CancellationToken cancellationToken);

/// <summary>
/// Port of a registry-tagged approver (<c>@approver(name=...)</c>): the <see cref="Approver"/> together with the
/// registry name written as <c>ApprovalEvent.approver</c> and the parameters it was created with (only those
/// explicitly passed, as <c>registry_params</c> records them), written to the log's <c>config.approval</c>.
/// </summary>
public sealed record ApproverDef(string Name, Approver Approve)
{
    public JsonObject Params { get; init; } = new();
}

/// <summary>
/// Port of the <c>"approver"</c> registry (<c>approval/_registry.py</c>): factories keyed by name so approval policy
/// files can name approvers. <c>auto</c> and <c>human</c> are registered by default; extensions register their own
/// (e.g. <c>"evaltools/bash_allowlist"</c>) with <see cref="Register"/>.
/// </summary>
public static class ApproverRegistry
{
    private static readonly ConcurrentDictionary<string, Func<JsonObject, ApproverDef>> Factories = new(StringComparer.Ordinal);

    static ApproverRegistry()
    {
        Register("auto", Approvers.AutoFromParams);
        Register("human", Approvers.HumanFromParams);
    }

    /// <summary>Registers (or replaces) the factory for <paramref name="name"/>; it receives the policy entry's <c>params</c>.</summary>
    public static void Register(string name, Func<JsonObject, ApproverDef> factory)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(name);
        ArgumentNullException.ThrowIfNull(factory);
        Factories[name] = factory;
    }

    /// <summary>Port of <c>registry_lookup("approver", name)</c> truthiness.</summary>
    public static bool IsRegistered(string name)
    {
        ArgumentNullException.ThrowIfNull(name);
        return Factories.ContainsKey(name);
    }

    /// <summary>Port of <c>create_registry_object("approver", name, params)</c>; an unregistered name is an <see cref="ArgumentException"/>.</summary>
    public static ApproverDef Create(string name, JsonObject? parameters = null)
    {
        ArgumentNullException.ThrowIfNull(name);
        if (!Factories.TryGetValue(name, out var factory))
        {
            throw new ArgumentException($"Approver '{name}' is not registered (register it with ApproverRegistry.Register).", nameof(name));
        }

        return factory(parameters ?? new JsonObject());
    }
}
